<?php $currency=trim((string)($institute['currency_symbol']??$institute['currency']??'PKR'));$total=array_sum(array_map(static fn($x)=>(float)$x['remaining_amount'],$outstanding)); ?>
<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><span class="module-eyebrow">Collections</span><h1>Outstanding Fee Balances</h1><p>Find defaulters by student, guardian, class, month or minimum balance.</p></div><a class="btn btn--secondary" href="<?=url('/admin/fees/collect')?>"><i data-lucide="badge-dollar-sign"></i>Collect fee</a></header>
<form class="filter-bar" method="get"><div class="module-field"><label>Search</label><input class="module-input" name="search" value="<?=e($search)?>" placeholder="Student, registration, guardian or invoice"></div><div class="module-field"><label>Month</label><input class="module-input" type="month" name="month" value="<?=e($selectedMonth)?>"></div><div class="module-field"><label>Class</label><select class="module-select" name="class"><option value="">All classes</option><?php foreach($classes as$c):?><option value="<?=$c['id']?>" <?=$selectedClass==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach?></select></div><div class="module-field"><label>Minimum outstanding</label><input class="module-input" type="number" min="0" step="0.01" name="minimum" value="<?=e($minimum)?>"></div><button class="btn btn--primary">Apply filters</button></form>
<div class="metric-grid"><div class="metric-card"><span>Defaulter invoices</span><strong><?=count($outstanding)?></strong></div><div class="metric-card"><span>Outstanding in view</span><strong><?=e($currency)?> <?=number_format($total,2)?></strong></div></div>
<section class="module-card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Student</th><th>Guardian contact</th><th>Class</th><th>Invoice / Month</th><th>Total</th><th>Paid</th><th>Outstanding</th><th>Actions</th></tr></thead><tbody><?php if(!$outstanding):?><tr><td colspan="8"><div class="compact-empty"><h3>No outstanding balances</h3><p>No invoice matches the selected filters.</p></div></td></tr><?php else:foreach($outstanding as$row):$message='Dear parent, '.$row['student_name'].' has an outstanding school fee of '.$currency.' '.number_format((float)$row['remaining_amount'],2).' for '.$row['fee_month'].'. Invoice: '.$row['invoice_no'].'.';?><tr><td><strong><?=e($row['student_name'])?></strong><br><small><?=e($row['registration_no'])?></small></td><td><?=e($row['father_name']?:'Guardian')?><br><small><?=e($row['mobile']?:'No mobile recorded')?></small></td><td><?=e($row['class_name'])?></td><td><?=e($row['invoice_no'])?><br><small><?=e($row['fee_month'])?></small></td><td><?=e($currency)?> <?=number_format((float)$row['total_amount'],2)?></td><td><?=e($currency)?> <?=number_format((float)$row['paid_amount'],2)?></td><td><strong><?=e($currency)?> <?=number_format((float)$row['remaining_amount'],2)?></strong></td><td><div class="table-actions"><a class="class-action-button" href="<?=url('/admin/fees/collect?student_id='.$row['student_id'].'&month='.$row['fee_month'])?>" aria-label="Collect fee"><i data-lucide="badge-dollar-sign"></i></a><a class="class-action-button" href="<?=url('/admin/reports/fee-invoice/'.$row['id'].'/pdf')?>" target="_blank" aria-label="Download voucher"><i data-lucide="file-down"></i></a><?php if($row['mobile']):?><form method="post" action="<?=url('/admin/whatsapp/open')?>" target="_blank"><?=csrf_field()?><input type="hidden" name="phone" value="<?=e($row['mobile'])?>"><input type="hidden" name="message" value="<?=e($message)?>"><button class="class-action-button" aria-label="Open WhatsApp reminder"><i data-lucide="message-circle"></i></button></form><?php endif?></div></td></tr><?php endforeach;endif?></tbody></table></div></section></div></div></main>
